- (void)searchSourceStorageWillProcessEditing:(NSNotification *)notification {
    NSTextStorage *storage = [notification object];
    if (storage != [textView textStorage] || !([storage editedMask] & NSTextStorageEditedCharacters)) return;
    // Every attached editor observes shared characters, including uncommitted composition.
    ++searchHighlightGeneration;
    [textView invalidateSearchHighlights];
}

source_highlight_request.source:
- (void)refreshSearchHighlights {
    NSUInteger generation = ++searchHighlightGeneration;
    [textView removeHighlightedTerms];
    NVBrowserSession *session = [self browserSession];
    NVSearchService *service = [[NVApplicationController sharedController] searchService];
    [service cancelLiteralRangesForOwner:session];
    if (!currentNote || ![prefsController highlightSearchTerms] || ![session searchResultsAreCurrent] || searchHasPendingComposition) return;
    NSInteger row = [notesTableView primarySelectedRow];
    if (row < 0) return;
    NSString *kind = [session matchKindAtIndex:row];
    if ([kind isEqual:@"retained"]) return;
    NSString *key = [[session rowKeyAtIndex:row] copy];
    NSString *displayedSource = [[textView string] copy];
    BOOL (^isCurrent)(void) = ^BOOL {
        return generation == searchHighlightGeneration && [session searchResultsAreCurrent] &&
            [[session rowKeyAtIndex:[notesTableView primarySelectedRow]] isEqual:key];
    };
    NVSearchLiteralRangesCompletion apply = ^(NSArray *ranges, NSString *source, NSError *error) {
        // Shared character notifications advance this generation immediately.
        // The worker compared immutable source copies before returning ranges.
        if (!error && isCurrent()) [textView setSearchHighlightRanges:ranges];
    };
    if ([kind isEqual:@"fuzzy"]) [session requestSourceHighlightsForRow:row completion:^(NSArray *ranges, NSString *source) {
        if (isCurrent()) [service validateSourceRanges:ranges source:source matchingSource:displayedSource owner:session completion:apply];
    }];
    else [service requestLiteralRangesInSource:[[currentNote contentString] string] matchingSource:displayedSource query:[session searchString] owner:session completion:apply];
    [displayedSource release]; [key release];
}

storage_attachment.source:
- (void)_setCurrentNote:(NoteObject *)aNote finishingEditing:(BOOL)finishOldEditing {
    if (currentNote == aNote) return;
    if (finishOldEditing) [self finishEditing];
    [self captureBodyPresentation];
    if (currentNote) {
        NSString *key = [NSString uuidStringWithBytes:*[currentNote uniqueNoteIDBytes]];
        [noteSelections setObject:NSStringFromRange([textView selectedRange]) forKey:key];
    }
    [currentNote release];
    currentNote = [aNote retain];
    NVNoteEditingSession *previousSession = [editingSession autorelease];
    editingSession = [[[NVApplicationController sharedController] editingSessionForNote:aNote] retain];
    NSTextStorage *storage = editingSession ? [editingSession textStorage] : emptyEditorStorage;
    NSLayoutManager *layout = [[textView layoutManager] retain];
    [[NSNotificationCenter defaultCenter] removeObserver:self name:NSTextStorageWillProcessEditingNotification object:[layout textStorage]];
    // Cancel the old note's deferred cleanup before this editor changes storage.
    [textView removeHighlightedTerms];
    // replaceTextStorage: moves every layout manager from the old storage.
    // Detach only this window's layout manager when switching notes.
    [[layout textStorage] removeLayoutManager:layout];
    [previousSession sourceLayoutDidDetach];
    [storage addLayoutManager:layout];
    if (editingSession) [[NSNotificationCenter defaultCenter] addObserver:self selector:@selector(searchSourceStorageWillProcessEditing:) name:NSTextStorageWillProcessEditingNotification object:storage];
    [editingSession sourceLayoutDidAttach];
    [layout release];
    [textView setAllowsUndo:NO];
    [self updateNoteHeader];
    [self updateBodyPresentation];
    if (!aNote) [self discardViewer];
    else if (viewingNote) [self updateViewerSnapshot];
}

editor_invalidation.source:
- (void)invalidateSearchHighlights {
    if (searchHighlightsInvalidated) return;
    searchHighlightsInvalidated = YES;
    // TextKit has not adjusted its glyph ranges during storage notifications.
    // Suppress stale backgrounds now and remove them after edit processing.
    [self performSelector:@selector(removeHighlightedTerms) withObject:nil afterDelay:0 inModes:@[NSRunLoopCommonModes]];
}

editor_cleanup.source:
- (void)removeHighlightedTerms {
    [NSObject cancelPreviousPerformRequestsWithTarget:self selector:@selector(removeHighlightedTerms) object:nil];
    if ([[self textStorage] editedMask] & NSTextStorageEditedCharacters) {
        searchHighlightsInvalidated = YES;
        // A nested run loop can run before endEditing. Avoid retrying at zero delay.
        [self performSelector:@selector(removeHighlightedTerms) withObject:nil afterDelay:0.01 inModes:@[NSRunLoopCommonModes]];
        return;
    }
    searchHighlightsInvalidated = NO;
    [[self layoutManager] removeTemporaryAttribute:NSBackgroundColorAttributeName forCharacterRange:NSMakeRange(0, [[self string] length])];
}

editor_publication.source:
- (void)setSearchHighlightRanges:(NSArray *)ranges {
    [self removeHighlightedTerms];
    if (searchHighlightsInvalidated) return;
    NSColor *color = [[self currentSearchHighlightAttributes] objectForKey:NSBackgroundColorAttributeName];
    if (!color) return;
    NSUInteger length = [[self string] length];
    NSUInteger displayed = 0;
    for (NSValue *value in ranges) {
        if (displayed++ == NVSearchMaximumDisplayedRanges) break;
        NSRange range = [value rangeValue];
        if (range.location <= length && range.length <= length - range.location && range.length)
            [[self layoutManager] addTemporaryAttribute:NSBackgroundColorAttributeName value:color forCharacterRange:range];
    }
}
